# Import of required libraries
import skyramp
import os
import time

from SkyrampUtils import (
    create_group,
    create_recipe,
    get_recipe_global,
    patch_recipe,
)


# URL for test requests
URL_localhost = skyramp.get_base_url("SKYRAMP_TEST_BASE_URL", "http://localhost:9000")


def test_integration():
    # Invocation of Skyramp Client
    client = skyramp.Client()
    # Definition of authentication header
    headers = {}
    if os.getenv("SKYRAMP_TEST_TOKEN") is not None:
        headers["Authorization"] = "Bearer " + os.getenv("SKYRAMP_TEST_TOKEN")

    # Declaration of variables
    recipes = "iso-tenant-probe"

    recipes_POST_response = create_recipe(client, headers, "Iso Tenant Probe")

    groups_POST_response = create_group(
        client, headers, skyramp.unique_suffix("iso-tenant-group")
    )

    assert skyramp.get_response_value(groups_POST_response, "name").startswith("iso-tenant-group")
    assert skyramp.get_response_value(groups_POST_response, "slug").startswith("iso-tenant-group")
    assert len(skyramp.get_response_value(groups_POST_response, "id")) == 36

    recipes_recipes_PATCH_response = patch_recipe(
        client,
        headers,
        recipes,
        skyramp.get_response_value(groups_POST_response, "id"),
    )

    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "slug") == recipes
    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "name") == "Iso Tenant Probe"
    assert len(skyramp.get_response_value(recipes_recipes_PATCH_response, "id")) == 36
    assert skyramp.get_response_value(recipes_recipes_PATCH_response, "groupId") == skyramp.get_response_value(groups_POST_response, "id")

    global_GET_response = get_recipe_global(
        client,
        headers,
        skyramp.get_response_value(recipes_recipes_PATCH_response, "id"),
    )

    assert skyramp.get_response_value(global_GET_response, "detail.message") == "Recipe not found"
    assert skyramp.get_response_value(global_GET_response, "detail.error") is True
    assert skyramp.check_schema(global_GET_response, r'''{"detail": {"exception": null}}''')


if __name__ == "__main__":
    test_integration()
